INSERT INTO `t_operation_log` VALUES (28, 1, 'admin', '项目管理', '编辑', '更新项目', 'PUT /api/project', '{\"name\":\"hoyozero-boot-test\",\"description\":\"测试\",\"gitUrl\":\"https://gitee.com/hoyozero/example-project.git\",\"branch\":\"master\",\"gitUsername\":\"wqexpore@163.com\",\"gitPassword\":\"wq850994281\",\"projectType\":\"JAVA\",\"buildCommand\":\"mvn clean package -DskipTests\",\"buildDir\":\"target/*.jar\",\"serverIds\":[2],\"autoDeploy\":1,\"deployScript\":\"#!/bin/bash\\n# Java 项目部署脚本\\n\\nAPP_PORT={{appPort}}\\nDEPLOY_DIR=\\\"{{uploadPath}}\\\"\\nLOG_FILE=\\\"$DEPLOY_DIR/app.log\\\"\\n\\necho \\\"========================================\\\"\\necho \\\"开始部署Java应用\\\"\\necho \\\"========================================\\\"\\n\\n# 1. 停止旧进程\\necho \\\"[步骤1] 正在停止旧进程...\\\"\\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\\nif [ ! -z \\\"$PID\\\" ]; then\\n  kill -15 $PID\\n  sleep 3\\n  if ps -p $PID > /dev/null 2>&1; then\\n    kill -9 $PID\\n    echo \\\"已强制停止进程: $PID\\\"\\n  else\\n    echo \\\"已优雅停止进程: $PID\\\"\\n  fi\\nelse\\n  echo \\\"未找到运行中的进程\\\"\\nfi\\n\\nsleep 2\\n\\n# 2. 备份旧版本（上传新jar前可能已有旧jar在运行）\\necho \\\"[步骤2] 备份旧版本...\\\"\\n# 查找所有jar文件（按修改时间排序）\\nJAR_FILES=($(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\\\.bak$\'))\\nJAR_COUNT=${#JAR_FILES[@]}\\n\\necho \\\"找到 $JAR_COUNT 个jar文件\\\"\\n\\nif [ $JAR_COUNT -gt 1 ]; then\\n  # 有多个jar，备份除了最新的之外的所有jar\\n  echo \\\"检测到多个jar文件，开始备份旧版本...\\\"\\n  for ((i=1; i<$JAR_COUNT; i++)); do\\n    OLD_JAR=\\\"${JAR_FILES[i]}\\\"\\n    OLD_JAR_NAME=$(basename \\\"$OLD_JAR\\\")\\n    BACKUP_NAME=\\\"${OLD_JAR_NAME%.jar}_$(date +%Y%m%d_%H%M%S).jar.bak\\\"\\n    mv \\\"$OLD_JAR\\\" \\\"$DEPLOY_DIR/$BACKUP_NAME\\\"\\n    echo \\\"已备份: $OLD_JAR_NAME -> $BACKUP_NAME\\\"\\n  done\\n  # 保留最近3个备份\\n  ls -t $DEPLOY_DIR/*.jar.bak 2>/dev/null | tail -n +4 | xargs rm -f 2>/dev/null\\nelif [ $JAR_COUNT -eq 1 ]; then\\n  echo \\\"只有一个jar文件，无需备份\\\"\\nelse\\n  echo \\\"未找到jar文件，可能是首次部署\\\"\\nfi\\n\\n# 3. 使用最新的jar\\necho \\\"[步骤3] 准备新版本...\\\"\\n# 重新查找jar文件（因为备份后可能只剩下最新的）\\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\\\.bak$\' | head -n 1)\\n\\nif [ -z \\\"$JAR_FILE\\\" ] || [ ! -f \\\"$JAR_FILE\\\" ]; then\\n  echo \\\"错误: 未找到可用的jar文件\\\"\\n  exit 1\\nfi\\n\\nJAR_NAME=$(basename \\\"$JAR_FILE\\\")\\necho \\\"找到jar文件: $JAR_NAME\\\"\\n...', '{\"code\":200,\"message\":\"操作成功\",\"data\":\"更新成功\"}', '0:0:0:0:0:0:0:1', NULL, 1, NULL, '2025-12-02 12:23:03');
