INSERT INTO `t_operation_log` VALUES (55, 1, 'admin', '项目管理', '新增', '创建项目', 'POST /api/project', '{\"name\":\"12\",\"description\":\"23\",\"gitUrl\":\"12\",\"branch\":\"23\",\"gitUsername\":\"23\",\"gitPassword\":\"23\",\"projectType\":\"JAVA\",\"buildCommand\":\"mvn clean package -DskipTests\",\"buildDir\":\"target/*.jar\",\"serverIds\":[2],\"autoDeploy\":0,\"deployScript\":\"#!/bin/bash\\n# Java 项目部署脚本\\n\\nAPP_PORT={{appPort}}\\nDEPLOY_DIR=\\\"{{uploadPath}}\\\"\\nLOG_FILE=\\\"$DEPLOY_DIR/app.log\\\"\\n\\necho \\\"========================================\\\"\\necho \\\"开始部署Java应用\\\"\\necho \\\"========================================\\\"\\n\\n# 1. 停止旧进程\\necho \\\"[步骤1] 正在停止旧进程...\\\"\\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\\nif [ ! -z \\\"$PID\\\" ]; then\\n  kill -15 $PID\\n  sleep 3\\n  if ps -p $PID > /dev/null 2>&1; then\\n    kill -9 $PID\\n    echo \\\"已强制停止进程: $PID\\\"\\n  else\\n    echo \\\"已优雅停止进程: $PID\\\"\\n  fi\\nelse\\n  echo \\\"未找到运行中的进程\\\"\\nfi\\n\\nsleep 2\\n\\n# 2. 查找新上传的jar（备份操作已在上传前完成）\\necho \\\"[步骤2] 查找jar文件...\\\"\\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\\\.bak$\' | head -n 1)\\n\\nif [ -z \\\"$JAR_FILE\\\" ] || [ ! -f \\\"$JAR_FILE\\\" ]; then\\n  echo \\\"错误: 未找到可用的jar文件\\\"\\n  exit 1\\nfi\\n\\nJAR_NAME=$(basename \\\"$JAR_FILE\\\")\\necho \\\"找到jar文件: $JAR_NAME\\\"\\n\\n# 3. 启动新应用\\necho \\\"[步骤3] 正在启动应用...\\\"\\ncd $DEPLOY_DIR\\n\\n# 清空旧日志\\n> $LOG_FILE\\n\\n# 后台启动应用\\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT \\\"$JAR_FILE\\\" > $LOG_FILE 2>&1 &\\nNEW_PID=$!\\n\\necho \\\"应用已启动，PID: $NEW_PID\\\"\\necho \\\"JAR文件: $JAR_NAME\\\"\\necho \\\"日志文件: $LOG_FILE\\\"\\n\\n# 4. 等待应用启动并实时显示日志\\necho \\\"[步骤4] 等待应用启动...\\\"\\necho \\\"----------------------------------------\\\"\\necho \\\"应用启动日志：\\\"\\necho \\\"----------------------------------------\\\"\\n\\n# 实时显示日志并检测启动成功\\nSTART_TIME=$(date +%s)\\nTIMEOUT=60\\nSTARTED=false\\n\\n# 使用 tail -f 实时显示日志，同时检测启动状态\\n(\\n  tail -f $LOG_FILE &\\n  TAIL_PID=$!\\n  \\n  while true; do\\n    CURRENT_TIME=$(date +%s)\\n    ELAPSED=$((CURRENT_TIME - START_TIME))\\n    \\n    # 检查超时\\n    if [ $ELAPSED -gt $TIMEOUT ]; then\\n      kill $TAIL_PID 2>/dev/null\\n      echo \\\"\\\"\\n      echo \\\"----------------------------------------\\\"\\n      echo \\\"警告: 应用启动超时（60秒）\\\"\\n      echo \\\"请检查...', '{\"code\":200,\"message\":\"操作成功\",\"data\":\"添加成功\"}', '0:0:0:0:0:0:0:1', NULL, 1, NULL, '2025-12-02 14:16:07');
