l -f 实时显示日志，同时检测启动状态\\n(\\n  tail -f $LOG_FILE &\\n  TAIL_PID=$!\\n  \\n  while true; do\\n    CURRENT_TIME=$(date +%s)\\n    ELAPSED=$((CURRENT_TIME - START_TIME))\\n    \\n    # 检查超时\\n    if [ $ELAPSED -gt $TIMEOUT ]; then\\n      kill $TAIL_PID 2>/dev/null\\n      echo \\\"\\\"\\n      echo \\\"-------------------------------...', '{\"code\":200,\"message\":\"操作成功\",\"data\":\"更新成功\"}', '0:0:0:0:0:0:0:1', NULL, 1, NULL, '2025-12-02 15:50:24');
