INSERT INTO `t_operation_log` VALUES (2000474898681548801, 1, 'admin', '项目管理', '新增', '创建项目', 'POST /api/project', '{\"name\":\"test001\",\"description\":\"\",\"gitUrl\":\"11\",\"branch\":\"master\",\"gitUsername\":\"\",\"gitPassword\":\"123456\",\"projectType\":\"JAVA\",\"env\":\"development\",\"buildCommand\":\"mvn clean package -DskipTests\",\"buildDir\":\"target/*.jar\",\"serverIds\":[\"1996104609289953282\"],\"autoDeploy\":1,\"appPort\":8080,\"deployPath\":\"/home/deploy/\",\"deployScript\":\"#!/bin/bash\\n# Java项目部署脚本\\n\\nAPP_NAME=\\\"\\\"\\nAPP_PORT=8080\\nDEPLOY_PATH=\\\"/home/deploy/\\\"\\n\\n# 进入部署目录\\ncd ${DEPLOY_PATH} || exit 1\\n\\n# 停止旧应用\\nif [ -f \\\"${APP_NAME}.pid\\\" ]; then\\n  OLD_PID=$(cat ${APP_NAME}.pid)\\n  if ps -p $OLD_PID > /dev/null; then\\n    echo \\\"停止旧应用 PID: $OLD_PID\\\"\\n    kill $OLD_PID\\n    sleep 3\\n  fi\\nfi\\n\\n# 备份旧版本\\nif [ -f \\\"${APP_NAME}.jar\\\" ]; then\\n  BACKUP_NAME=\\\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\\\"\\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\\n  echo \\\"已备份旧版本: ${BACKUP_NAME}\\\"\\nfi\\n\\n# 启动新应用\\necho \\\"启动新应用...\\\"\\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\\necho $! > ${APP_NAME}.pid\\n\\necho \\\"部署完成！应用端口: ${APP_PORT}\\\"\\necho \\\"查看日志: tail -f logs/${APP_NAME}.log\\\"\"}', '{\"code\":200,\"message\":\"操作成功\",\"data\":\"添加成功\"}', '0:0:0:0:0:0:0:1', NULL, 1, NULL, '2025-12-15 15:55:58');
