\"\\nsleep 3\\n# 输出启动日志，最多10秒\\ntimeout 10 tail -f logs/${APP_NAME}.log 2>/dev/null &\\nTAIL_PID=$!\\nsleep 10\\nkill $TAIL_PID 2>/dev/null\\necho \\\"================================================\\\"\\n\\n# 检查进程是否运行\\nif ps -p $NEW_PID > /dev/null 2>&1; then\\n  echo \\\"[SUCCESS] Application is runni...', '{\"code\":200,\"message\":\"操作成功\",\"data\":\"添加成功\"}', '0:0:0:0:0:0:0:1', NULL, 1, NULL, '2025-12-25 16:38:07');
