INSERT INTO `t_operation_log` VALUES (2004110387472936962, 1, 'admin', '项目管理', '编辑', '更新项目', 'PUT /api/project', '{\"name\":\"order-spider\",\"description\":\"\",\"gitUrl\":\"https://gitee.com/hoyozero/order-sp.git\",\"branch\":\"master\",\"projectDir\":\"backend\",\"gitUsername\":\"wqexpore@163.com\",\"gitPassword\":\"wq850994281\",\"projectType\":\"JAVA\",\"env\":\"production\",\"groupId\":\"2004091385556185089\",\"buildCommand\":\"mvn clean package -DskipTests\",\"buildDir\":\"target/*.jar\",\"serverIds\":[\"2003720543307436034\"],\"autoDeploy\":1,\"appPort\":8082,\"deployPath\":\"/www/wwwroot/\",\"deployScript\":\"#!/bin/bash\\n# Java项目部署脚本\\n\\nAPP_NAME=\\\"order-spider\\\"\\nAPP_PORT={{appPort}}\\nDEPLOY_PATH=\\\"{{uploadPath}}\\\"\\n\\n# 进入部署目录\\ncd ${DEPLOY_PATH} || exit 1\\n\\n# 创建必要的目录\\nmkdir -p logs backup\\n\\n# 停止旧应用\\nif [ -f \\\"${APP_NAME}.pid\\\" ]; then\\n  OLD_PID=$(cat ${APP_NAME}.pid)\\n  if ps -p $OLD_PID > /dev/null 2>&1; then\\n    echo \\\"[INFO] Stopping old application (PID: $OLD_PID)...\\\"\\n    kill $OLD_PID\\n    sleep 3\\n    # 强制停止\\n    if ps -p $OLD_PID > /dev/null 2>&1; then\\n      kill -9 $OLD_PID\\n    fi\\n  fi\\n  rm -f ${APP_NAME}.pid\\nfi\\n\\n# 备份旧版本\\nif [ -f \\\"${APP_NAME}.jar\\\" ]; then\\n  BACKUP_NAME=\\\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\\\"\\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\\n  echo \\\"[INFO] Backup old version: ${BACKUP_NAME}\\\"\\nfi\\n\\n# 查找并重命名新上传的jar包\\necho \\\"[INFO] Looking for uploaded jar file...\\\"\\nUPLOADED_JAR=$(ls -t *.jar 2>/dev/null | head -n 1)\\nif [ -n \\\"$UPLOADED_JAR\\\" ]; then\\n  if [ \\\"$UPLOADED_JAR\\\" != \\\"${APP_NAME}.jar\\\" ]; then\\n    mv \\\"$UPLOADED_JAR\\\" \\\"${APP_NAME}.jar\\\"\\n    echo \\\"[INFO] Renamed $UPLOADED_JAR to ${APP_NAME}.jar\\\"\\n  fi\\nelse\\n  echo \\\"[ERROR] No jar file found in current directory!\\\"\\n  exit 1\\nfi\\n\\n# 清空旧日志\\necho \\\"\\\" > logs/${APP_NAME}.log\\n\\n# 启动新应用\\necho \\\"[INFO] Starting new application...\\\"\\necho \\\"[INFO] Application port: ${APP_PORT}\\\"\\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\\nNEW_PID=$!\\necho $NEW_PID > ${APP_NAME}.pid\\necho \\\"[INFO] Application PID: $NEW_PID\\\"\\n\\n# 等待应用启动（输出启动日志）\\necho \\\"\\\"\\necho \\\"[LOG] Application startup logs:\\\"\\...', '{\"code\":200,\"message\":\"操作成功\",\"data\":\"更新成功\"}', '0:0:0:0:0:0:0:1', NULL, 1, NULL, '2025-12-25 16:42:06');
