INSERT INTO `t_plugin` VALUES (23, 'Git', 'git', 'BASE_ENV', '分布式版本控制系统', 'GitBranchSharp', '[\"2.40\", \"2.41\", \"latest\"]', 'latest', '#!/bin/bash\r\nyum install -y git\r\ngit --version', '#!/bin/bash\r\nyum remove -y git', NULL, 1, 'ENABLED', '2025-12-01 14:06:10', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (24, 'JDK 8', 'jdk8', 'BASE_ENV', 'Java Development Kit 8', 'CodeSharp', '[\"8u391\", \"8u392\", \"8u401\"]', '8u401', '#!/bin/bash\r\nyum install -y java-1.8.0-openjdk java-1.8.0-openjdk-devel\r\njava -version', '#!/bin/bash\r\nyum remove -y java-1.8.0-openjdk java-1.8.0-openjdk-devel', NULL, 2, 'ENABLED', '2025-12-01 14:06:10', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (25, 'JDK 17', 'jdk17', 'BASE_ENV', 'Java Development Kit 17 LTS', 'CodeSharp', '[\"17.0.9\", \"17.0.10\", \"17.0.11\"]', '17.0.11', '#!/bin/bash\r\nyum install -y java-17-openjdk java-17-openjdk-devel\r\njava -version', '#!/bin/bash\r\nyum remove -y java-17-openjdk java-17-openjdk-devel', NULL, 3, 'ENABLED', '2025-12-01 14:06:10', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (26, 'Node.js LTS', 'nodejs', 'BASE_ENV', 'JavaScript 运行时环境', 'LogoNodejs', '[\"18.19.0\", \"20.11.0\", \"latest\"]', '20.11.0', '#!/bin/bash\r\n# 安装 Node.js 20.x LTS\r\ncurl -fsSL https://rpm.nodesource.com/setup_20.x | bash -\r\nyum install -y nodejs\r\nnode --version\r\nnpm --version', '#!/bin/bash\r\nyum remove -y nodejs', NULL, 4, 'ENABLED', '2025-12-01 14:06:10', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (28, 'Python 3', 'python3', 'BASE_ENV', 'Python 编程语言', 'LogoPython', '[\"3.10\", \"3.11\", \"3.12\"]', '3.11', '#!/bin/bash\r\nyum install -y python3 python3-pip\r\npython3 --version\r\npip3 --version', '#!/bin/bash\r\nyum remove -y python3 python3-pip', NULL, 6, 'ENABLED', '2025-12-01 14:06:10', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (29, 'Maven', 'maven', 'BASE_ENV', 'Java 项目管理工具', 'ConstructSharp', '[\"3.8.8\", \"3.9.6\", \"3.9.11\"]', '3.9.11', '#!/bin/bash\r\nVERSION={{version}}\r\ncd /tmp\r\nwget https://dlcdn.apache.org/maven/maven-3/${VERSION}/binaries/apache-maven-${VERSION}-bin.tar.gz\r\ntar -zxf apache-maven-${VERSION}-bin.tar.gz -C /usr/local/\r\nln -sf /usr/local/apache-maven-${VERSION}/bin/mvn /usr/bin/mvn\r\nrm -f apache-maven-${VERSION}-bin.tar.gz\r\nmvn --version', '#!/bin/bash\r\nrm -rf /usr/local/apache-maven-*\r\nrm -f /usr/bin/mvn', NULL, 7, 'ENABLED', '2025-12-01 14:06:10', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (30, 'Nginx', 'nginx', 'BASE_ENV', '高性能 Web 服务器和反向代理', 'ServerSharp', '[\"1.24\", \"1.26\", \"latest\"]', 'latest', '#!/bin/bash\r\n# 安装 Nginx\r\nyum install -y nginx\r\n\r\n# 启动并设置开机自启\r\nsystemctl start nginx\r\nsystemctl enable nginx\r\n\r\n# 检查版本和状态\r\nnginx -v\r\nsystemctl status nginx | grep \"Active\"\r\n\r\necho \"Nginx 安装完成！\"\r\necho \"访问地址: http://服务器IP\"', '#!/bin/bash\r\n# 停止服务\r\nsystemctl stop nginx\r\nsystemctl disable nginx\r\n\r\n# 卸载 Nginx\r\nyum remove -y nginx\r\n\r\n# 清理配置文件（可选）\r\n# rm -rf /etc/nginx\r\n# rm -rf /var/log/nginx\r\n\r\necho \"Nginx 已卸载\"', NULL, 5, 'ENABLED', '2025-12-25 16:30:00', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin` VALUES (31, 'Docker', 'docker', 'BASE_ENV', '应用容器引擎', 'CubeSharp', '[\"24.0\", \"25.0\", \"latest\"]', 'latest', '#!/bin/bash\r\n# 卸载旧版本\r\nyum remove -y docker docker-client docker-client-latest docker-common docker-latest docker-latest-logrotate docker-logrotate docker-engine\r\n\r\n# 安装依赖\r\nyum install -y yum-utils device-mapper-persistent-data lvm2\r\n\r\n# 添加 Docker 仓库\r\nyum-config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo\r\n\r\n# 安装 Docker\r\nyum install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\r\n\r\n# 启动 Docker\r\nsystemctl start docker\r\nsystemctl enable docker\r\n\r\n# 验证安装\r\ndocker --version\r\ndocker compose version\r\n\r\n# 配置 Docker 镜像加速（阿里云）\r\nmkdir -p /etc/docker\r\ncat > /etc/docker/daemon.json <<EOF\r\n{\r\n  \"registry-mirrors\": [\"https://mirror.ccs.tencentyun.com\"],\r\n  \"log-driver\": \"json-file\",\r\n  \"log-opts\": {\r\n    \"max-size\": \"100m\",\r\n    \"max-file\": \"3\"\r\n  }\r\n}\r\nEOF\r\n\r\n# 重启 Docker\r\nsystemctl daemon-reload\r\nsystemctl restart docker\r\n\r\necho \"Docker 安装完成！\"\r\necho \"运行测试: docker run hello-world\"', '#!/bin/bash\r\n# 停止所有容器\r\ndocker stop $(docker ps -aq) 2>/dev/null\r\n\r\n# 删除所有容器\r\ndocker rm $(docker ps -aq) 2>/dev/null\r\n\r\n# 删除所有镜像\r\ndocker rmi $(docker images -q) 2>/dev/null\r\n\r\n# 停止 Docker 服务\r\nsystemctl stop docker\r\nsystemctl disable docker\r\n\r\n# 卸载 Docker\r\nyum remove -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\r\n\r\n# 清理数据（可选，会删除所有 Docker 数据）\r\n# rm -rf /var/lib/docker\r\n# rm -rf /var/lib/containerd\r\n# rm -rf /etc/docker\r\n\r\necho \"Docker 已卸载\"', NULL, 8, 'ENABLED', '2025-12-25 16:30:00', '2025-12-25 16:30:00', 0);
INSERT INTO `t_plugin_copy1` VALUES (1, 'Git', 'git', 'BASE_ENV', '分布式版本控制系统', 'GitBranchSharp', '[\"2.40\", \"2.41\", \"latest\"]', 'latest', '#!/bin/bash\r\necho \"开始安装 Git ${VERSION}...\"\r\nif command -v git &> /dev/null; then\r\n    echo \"Git 已安装，版本: $(git --version)\"\r\n    exit 0\r\nfi\r\nyum install -y git || apt-get install -y git\r\necho \"Git 安装完成: $(git --version)\"', '#!/bin/bash\r\necho \"开始卸载 Git...\"\r\nyum remove -y git || apt-get remove -y git\r\necho \"Git 卸载完成\"', NULL, 1, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (2, 'JDK 8', 'jdk8', 'BASE_ENV', 'Java Development Kit 8', 'CodeSharp', '[\"8u391\", \"8u392\", \"8u401\"]', '8u401', '#!/bin/bash\r\necho \"开始安装 JDK 8 (${VERSION})...\"\r\nmkdir -p ${INSTALL_PATH}\r\ncd /tmp\r\nwget https://download.oracle.com/otn/java/jdk/${VERSION}/jdk-${VERSION}-linux-x64.tar.gz\r\ntar -zxvf jdk-${VERSION}-linux-x64.tar.gz -C ${INSTALL_PATH}\r\necho \"export JAVA_HOME=${INSTALL_PATH}/jdk1.8.0_${VERSION#8u}\" >> ~/.bashrc\r\necho \"export PATH=$JAVA_HOME/bin:$PATH\" >> ~/.bashrc\r\nsource ~/.bashrc\r\necho \"JDK 8 安装完成\"', '#!/bin/bash\r\necho \"开始卸载 JDK 8...\"\r\nrm -rf ${INSTALL_PATH}\r\nsed -i \"/JAVA_HOME/d\" ~/.bashrc\r\necho \"JDK 8 卸载完成\"', NULL, 2, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (3, 'JDK 17', 'jdk17', 'BASE_ENV', 'Java Development Kit 17 LTS', 'CodeSharp', '[\"17.0.9\", \"17.0.10\", \"17.0.11\"]', '17.0.11', '#!/bin/bash\r\necho \"开始安装 JDK 17 (${VERSION})...\"\r\nmkdir -p ${INSTALL_PATH}\r\ncd /tmp\r\nwget https://download.oracle.com/java/17/latest/jdk-17_linux-x64_bin.tar.gz\r\ntar -zxvf jdk-17_linux-x64_bin.tar.gz -C ${INSTALL_PATH}\r\necho \"export JAVA_HOME=${INSTALL_PATH}/jdk-17\" >> ~/.bashrc\r\necho \"export PATH=$JAVA_HOME/bin:$PATH\" >> ~/.bashrc\r\nsource ~/.bashrc\r\necho \"JDK 17 安装完成\"', '#!/bin/bash\r\necho \"开始卸载 JDK 17...\"\r\nrm -rf ${INSTALL_PATH}\r\nsed -i \"/JAVA_HOME/d\" ~/.bashrc\r\necho \"JDK 17 卸载完成\"', NULL, 3, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (4, 'Node.js LTS', 'nodejs', 'BASE_ENV', 'JavaScript 运行时环境', 'LogoNodejs', '[\"18.19.0\", \"20.11.0\", \"latest\"]', '20.11.0', '#!/bin/bash\r\necho \"开始安装 Node.js ${VERSION}...\"\r\ncurl -fsSL https://rpm.nodesource.com/setup_20.x | bash -\r\nyum install -y nodejs || apt-get install -y nodejs\r\necho \"Node.js 安装完成: $(node --version)\"\r\necho \"NPM 版本: $(npm --version)\"', '#!/bin/bash\r\necho \"开始卸载 Node.js...\"\r\nyum remove -y nodejs || apt-get remove -y nodejs\r\necho \"Node.js 卸载完成\"', NULL, 4, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (5, 'Docker', 'docker', 'BASE_ENV', '容器化平台', 'LogoDocker', '[\"24.0\", \"25.0\", \"latest\"]', 'latest', '#!/bin/bash\r\necho \"开始安装 Docker...\"\r\ncurl -fsSL https://get.docker.com | bash\r\nsystemctl start docker\r\nsystemctl enable docker\r\necho \"Docker 安装完成: $(docker --version)\"', '#!/bin/bash\r\necho \"开始卸载 Docker...\"\r\nsystemctl stop docker\r\nyum remove -y docker-ce docker-ce-cli containerd.io || apt-get remove -y docker-ce docker-ce-cli containerd.io\r\nrm -rf /var/lib/docker\r\necho \"Docker 卸载完成\"', NULL, 5, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (6, 'Python 3', 'python3', 'BASE_ENV', 'Python 编程语言', 'LogoPython', '[\"3.10\", \"3.11\", \"3.12\"]', '3.11', '#!/bin/bash\r\necho \"开始安装 Python ${VERSION}...\"\r\nyum install -y python3 python3-pip || apt-get install -y python3 python3-pip\r\necho \"Python 安装完成: $(python3 --version)\"\r\necho \"Pip 版本: $(pip3 --version)\"', '#!/bin/bash\r\necho \"开始卸载 Python 3...\"\r\nyum remove -y python3 python3-pip || apt-get remove -y python3 python3-pip\r\necho \"Python 3 卸载完成\"', NULL, 6, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (7, 'Maven', 'maven', 'BASE_ENV', 'Java 项目管理工具', 'ConstructSharp', '[\"3.8.8\", \"3.9.6\", \"latest\"]', '3.9.6', '#!/bin/bash\r\necho \"开始安装 Maven ${VERSION}...\"\r\nmkdir -p ${INSTALL_PATH}\r\ncd /tmp\r\nwget https://dlcdn.apache.org/maven/maven-3/${VERSION}/binaries/apache-maven-${VERSION}-bin.tar.gz\r\ntar -zxvf apache-maven-${VERSION}-bin.tar.gz -C ${INSTALL_PATH}\r\necho \"export MAVEN_HOME=${INSTALL_PATH}/apache-maven-${VERSION}\" >> ~/.bashrc\r\necho \"export PATH=$MAVEN_HOME/bin:$PATH\" >> ~/.bashrc\r\nsource ~/.bashrc\r\necho \"Maven 安装完成: $(mvn --version)\"', '#!/bin/bash\r\necho \"开始卸载 Maven...\"\r\nrm -rf ${INSTALL_PATH}\r\nsed -i \"/MAVEN_HOME/d\" ~/.bashrc\r\necho \"Maven 卸载完成\"', NULL, 7, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (8, 'Nginx', 'nginx', 'MIDDLEWARE', '高性能 Web 服务器', 'ServerSharp', '[\"1.24\", \"1.25\", \"latest\"]', 'latest', '#!/bin/bash\r\necho \"开始安装 Nginx...\"\r\nyum install -y nginx || apt-get install -y nginx\r\nsystemctl start nginx\r\nsystemctl enable nginx\r\necho \"Nginx 安装完成: $(nginx -v)\"', '#!/bin/bash\r\necho \"开始卸载 Nginx...\"\r\nsystemctl stop nginx\r\nyum remove -y nginx || apt-get remove -y nginx\r\necho \"Nginx 卸载完成\"', NULL, 1, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (9, 'MySQL 8', 'mysql', 'MIDDLEWARE', '关系型数据库', 'ServerSharp', '[\"8.0.35\", \"8.0.36\", \"latest\"]', '8.0.36', '#!/bin/bash\r\necho \"开始安装 MySQL 8...\"\r\nyum install -y mysql-server || apt-get install -y mysql-server\r\nsystemctl start mysqld\r\nsystemctl enable mysqld\r\necho \"MySQL 安装完成\"', '#!/bin/bash\r\necho \"开始卸载 MySQL...\"\r\nsystemctl stop mysqld\r\nyum remove -y mysql-server || apt-get remove -y mysql-server\r\nrm -rf /var/lib/mysql\r\necho \"MySQL 卸载完成\"', NULL, 2, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (10, 'Redis', 'redis', 'MIDDLEWARE', '内存数据库', 'ServerSharp', '[\"7.0\", \"7.2\", \"latest\"]', '7.2', '#!/bin/bash\r\necho \"开始安装 Redis...\"\r\nyum install -y redis || apt-get install -y redis-server\r\nsystemctl start redis\r\nsystemctl enable redis\r\necho \"Redis 安装完成\"', '#!/bin/bash\r\necho \"开始卸载 Redis...\"\r\nsystemctl stop redis\r\nyum remove -y redis || apt-get remove -y redis-server\r\necho \"Redis 卸载完成\"', NULL, 3, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_copy1` VALUES (11, 'MongoDB', 'mongodb', 'MIDDLEWARE', 'NoSQL 文档数据库', 'ServerSharp', '[\"6.0\", \"7.0\", \"latest\"]', '7.0', '#!/bin/bash\r\necho \"开始安装 MongoDB...\"\r\n# 配置 MongoDB yum 源\r\ncat > /etc/yum.repos.d/mongodb-org-7.0.repo <<EOF\r\n[mongodb-org-7.0]\r\nname=MongoDB Repository\r\nbaseurl=https://repo.mongodb.org/yum/redhat/$releasever/mongodb-org/7.0/x86_64/\r\ngpgcheck=1\r\nenabled=1\r\ngpgkey=https://www.mongodb.org/static/pgp/server-7.0.asc\r\nEOF\r\nyum install -y mongodb-org\r\nsystemctl start mongod\r\nsystemctl enable mongod\r\necho \"MongoDB 安装完成\"', '#!/bin/bash\r\necho \"开始卸载 MongoDB...\"\r\nsystemctl stop mongod\r\nyum remove -y mongodb-org\r\nrm -rf /var/lib/mongo\r\necho \"MongoDB 卸载完成\"', NULL, 4, 'ENABLED', '2025-12-01 11:52:33', '2025-12-01 11:52:33', 0);
INSERT INTO `t_plugin_install` VALUES (1, 1, 1, 'latest', 'UNINSTALLING', '========================================\n开始安装插件: Git\n版本: latest\n========================================\n\n[SSH] 连接服务器: 192.0.2.10\n[SSH] 连接成功\n\n[安装] 执行安装脚本...\n----------------------------------------\n开始安装 Git latest...\n----------------------------------------\n\n[完成] 插件安装成功！\n', '/usr/local/git', NULL, '1', '2025-12-01 13:39:38', '2025-12-01 13:42:54', 1);
