INSERT INTO `t_plugin_install` VALUES (23, 2, 34, 'latest', 'UNINSTALLING', '========================================\n开始安装插件: 宝塔面板 (latest)\n目标服务器: 192.0.2.10\n========================================\n\n[SSH] 连接服务器: 192.0.2.10\n[SSH] 连接成功\n\n[安装] 执行安装命令: #!/bin/bash\necho \"========================================\"\necho \"开始安装宝塔面板...\"\necho \"========================================\"\n\n# 检查是否已安装\nif [ -f \"/www/server/panel/BT-Panel\" ]; then\n    echo \"宝塔面板已安装\"\n    bt default\n    exit 0\nfi\n\n# 安装必要依赖\nyum install -y wget curl\n\n# 下载并执行安装脚本\nif [ -f /etc/redhat-release ]; then\n    echo \"检测到 CentOS/RHEL 系统\"\n    wget -O install.sh https://download.bt.cn/install/install_6.0.sh && sh install.sh ed8484bec <<< \"y\"\nelif [ -f /etc/debian_version ]; then\n    echo \"检测到 Debian/Ubuntu 系统\"\n    wget -O install.sh https://download.bt.cn/install/install-ubuntu_6.0.sh && bash install.sh ed8484bec <<< \"y\"\nelse\n    echo \"不支持的操作系统\"\n    exit 1\nfi\n\necho \"\"\necho \"========================================\"\necho \"宝塔面板安装完成！\"\necho \"使用 bt default 查看面板信息\"\necho \"========================================\"\n[脚本] 检测到多行脚本，准备执行...\n[脚本] 已上传脚本到服务器: /tmp/hoyozero_plugin_1764665241125.sh\n[脚本] 已设置执行权限\n[脚本] 开始执行...\n----------------------------------------\n========================================\n开始安装宝塔面板...\n========================================\nLast metadata expiration check: 0:30:03 ago on Tue 02 Dec 2025 04:17:19 PM CST.\nPackage wget-1.19.5-12.0.1.al8.x86_64 is already installed.\nPackage curl-7.61.1-35.0.2.al8.3.x86_64 is already installed.\nDependencies resolved.\nNothing to do.\nComplete!\n检测到 CentOS/RHEL 系统\n\n+----------------------------------------------------------------------\n| Bt-WebPanel FOR CentOS/Ubuntu/Debian\n+----------------------------------------------------------------------\n| Copyright © 2015-2099 BT-SOFT(http://www.bt.cn) All rights reserved.\n+----------------------------------------------------------------------\n| The WebPanel URL will be http://SERVER_IP:40506 when installed.\n+----------------------------------------------------------------------\n| 为了您的正常使用，请确保使用全新或纯净的系统安装宝塔面板，不支持已部署项目/环境的系统安装\n+----------------------------------------------------------------------\n\n----------------------------------------------------\n检查已有其他Web/mysql环境，安装宝塔可能影响现有站点及数据\nWeb/mysql service is alreday installed,Can\'t install panel\n----------------------------------------------------\n已知风险/Enter yes to force installation\n------------\n取消安装\n\n========================================\n宝塔面板安装完成！\n使用 bt default 查看面板信息\n========================================\n[STDERR] --2025-12-02 16:47:25--  https://download.bt.cn/install/install_6.0.sh\n[STDERR] Resolving download.bt.cn (download.bt.cn)... 211.99.112.70, 240e:f7:ef00:3:0:7:8000:125\n[STDERR] Connecting to download.bt.cn (download.bt.cn)|211.99.112.70|:443... connected.\n[STDERR] HTTP request sent, awaiting response... 200 OK\n[STDERR] Length: 50597 (49K) [application/octet-stream]\n[STDERR] Saving to: ‘install.sh’\n[STDERR] \n[STDERR]      0K .......... .......... .......... .......... ......... 100% 1.23M=0.04s\n[STDERR] \n[STDERR] 2025-12-02 16:47:26 (1.23 MB/s) - ‘install.sh’ saved [50597/50597]\n[STDERR] \n----------------------------------------\n[脚本] 执行成功\n[脚本] 已清理临时文件\n\n========================================\n安装成功！\n========================================\n[SSH] 连接已关闭\n', NULL, '2025-12-02 16:47:21', '1', '2025-12-02 16:47:21', '2025-12-02 16:47:59', 1);
