INSERT INTO `t_project` VALUES (1, NULL, 'hoyozero-boot-test', '测试', 'https://gitee.com/hoyozero/example-project.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java 项目部署脚本\n\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署Java应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 备份旧版本（上传新jar前可能已有旧jar在运行）\necho \"[步骤2] 备份旧版本...\"\n# 查找所有jar文件（按修改时间排序）\nJAR_FILES=($(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\.bak$\'))\nJAR_COUNT=${#JAR_FILES[@]}\n\necho \"找到 $JAR_COUNT 个jar文件\"\n\nif [ $JAR_COUNT -gt 1 ]; then\n  # 有多个jar，备份除了最新的之外的所有jar\n  echo \"检测到多个jar文件，开始备份旧版本...\"\n  for ((i=1; i<$JAR_COUNT; i++)); do\n    OLD_JAR=\"${JAR_FILES[i]}\"\n    OLD_JAR_NAME=$(basename \"$OLD_JAR\")\n    BACKUP_NAME=\"${OLD_JAR_NAME%.jar}_$(date +%Y%m%d_%H%M%S).jar.bak\"\n    mv \"$OLD_JAR\" \"$DEPLOY_DIR/$BACKUP_NAME\"\n    echo \"已备份: $OLD_JAR_NAME -> $BACKUP_NAME\"\n  done\n  # 保留最近3个备份\n  ls -t $DEPLOY_DIR/*.jar.bak 2>/dev/null | tail -n +4 | xargs rm -f 2>/dev/null\nelif [ $JAR_COUNT -eq 1 ]; then\n  echo \"只有一个jar文件，无需备份\"\nelse\n  echo \"未找到jar文件，可能是首次部署\"\nfi\n\n# 3. 使用最新的jar\necho \"[步骤3] 准备新版本...\"\n# 重新查找jar文件（因为备份后可能只剩下最新的）\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\.bak$\' | head -n 1)\n\nif [ -z \"$JAR_FILE\" ] || [ ! -f \"$JAR_FILE\" ]; then\n  echo \"错误: 未找到可用的jar文件\"\n  exit 1\nfi\n\nJAR_NAME=$(basename \"$JAR_FILE\")\necho \"找到jar文件: $JAR_NAME\"\n\n# 4. 启动新应用\necho \"[步骤4] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT \"$JAR_FILE\" > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"JAR文件: $JAR_NAME\"\necho \"日志文件: $LOG_FILE\"\n\n# 5. 等待应用启动并实时显示日志\necho \"[步骤5] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n  \n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n    \n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy222/', 8888, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', 1, '2025-11-28 11:37:12', '2025-12-03 14:34:07', 1, 'development');
INSERT INTO `t_project` VALUES (2, NULL, 'hoyozero-test', '后台测试', 'https://gitee.com/hoyozero/example-project.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# 自动生成的部署脚本\n\nAPP_NAME=\"app\"\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nJAR_FILE=$(ls $DEPLOY_DIR/*.jar | grep -v \'\\.bak$\' | head -n 1)\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 备份旧版本\necho \"[步骤2] 备份旧版本...\"\nif [ -f \"$DEPLOY_DIR/app.jar\" ]; then\n  BACKUP_NAME=\"app_$(date +%Y%m%d_%H%M%S).jar.bak\"\n  mv $DEPLOY_DIR/app.jar $DEPLOY_DIR/$BACKUP_NAME\n  echo \"已备份为: $BACKUP_NAME\"\n  ls -t $DEPLOY_DIR/*.jar.bak 2>/dev/null | tail -n +4 | xargs rm -f 2>/dev/null\nfi\n\n# 3. 重命名新上传的jar\necho \"[步骤3] 准备新版本...\"\nif [ -f \"$JAR_FILE\" ]; then\n  cp $JAR_FILE $DEPLOY_DIR/app.jar\n  echo \"已准备新版本: app.jar\"\nelse\n  echo \"错误: 未找到jar文件\"\n  exit 1\nfi\n\n# 4. 启动新应用\necho \"[步骤4] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT app.jar > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"日志文件: $LOG_FILE\"\n\n# 5. 等待应用启动并实时显示日志\necho \"[步骤5] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n  \n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n    \n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/', 8888, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', 1, '2025-11-28 16:01:11', '2025-12-01 17:00:55', 1, 'development');
INSERT INTO `t_project` VALUES (3, NULL, 'hoyozero-vue', '前端项目', 'https://gitee.com/hoyozero/hoyozero-vue-deploy.git', 'master', 'wqexpore@163.com', 'wq850994281', 0, '#!/bin/bash\n# 自动生成的部署脚本\n\nAPP_NAME=\"app\"\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nJAR_FILE=$(ls $DEPLOY_DIR/*.jar | grep -v \'\\.bak$\' | head -n 1)\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 备份旧版本\necho \"[步骤2] 备份旧版本...\"\nif [ -f \"$DEPLOY_DIR/app.jar\" ]; then\n  BACKUP_NAME=\"app_$(date +%Y%m%d_%H%M%S).jar.bak\"\n  mv $DEPLOY_DIR/app.jar $DEPLOY_DIR/$BACKUP_NAME\n  echo \"已备份为: $BACKUP_NAME\"\n  ls -t $DEPLOY_DIR/*.jar.bak 2>/dev/null | tail -n +4 | xargs rm -f 2>/dev/null\nfi\n\n# 3. 重命名新上传的jar\necho \"[步骤3] 准备新版本...\"\nif [ -f \"$JAR_FILE\" ]; then\n  cp $JAR_FILE $DEPLOY_DIR/app.jar\n  echo \"已准备新版本: app.jar\"\nelse\n  echo \"错误: 未找到jar文件\"\n  exit 1\nfi\n\n# 4. 启动新应用\necho \"[步骤4] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT app.jar > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"日志文件: $LOG_FILE\"\n\n# 5. 等待应用启动并实时显示日志\necho \"[步骤5] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n  \n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n    \n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/', 8080, 'VUE', NULL, 'npm install && npm run build', 'dist', 1, '2025-11-28 16:07:30', '2025-11-28 16:21:01', 1, 'development');
INSERT INTO `t_project` VALUES (4, NULL, 'hoyozero-vue', '', 'https://gitee.com/hoyozero/hoyozero-vue-deploy.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Vue 项目部署脚本\n\nDEPLOY_DIR=\"{{uploadPath}}\"\nWEB_ROOT=\"/www/wwwroot\"\nPROJECT_NAME=\"{{projectName}}\"\nTARGET_DIR=\"$WEB_ROOT/$PROJECT_NAME\"\nBACKUP_DIR=\"$WEB_ROOT/backup\"\n\necho \"========================================\"\necho \"开始部署Vue项目\"\necho \"========================================\"\n\n# 1. 备份旧版本\necho \"[步骤1] 备份旧版本...\"\nif [ -d \"$TARGET_DIR\" ]; then\n  mkdir -p $BACKUP_DIR\n  BACKUP_NAME=\"${PROJECT_NAME}_$(date +%Y%m%d_%H%M%S)\"\n  mv $TARGET_DIR $BACKUP_DIR/$BACKUP_NAME\n  echo \"已备份为: $BACKUP_NAME\"\n  \n  # 保留最近3个备份\n  ls -t $BACKUP_DIR | grep \"^${PROJECT_NAME}_\" | tail -n +4 | xargs -I {} rm -rf $BACKUP_DIR/{}\nfi\n\n# 2. 部署新版本\necho \"[步骤2] 部署新版本...\"\nmkdir -p $TARGET_DIR\n\n# 检查是否为压缩包\nif [ -f \"$DEPLOY_DIR/dist.zip\" ]; then\n  echo \"检测到 dist.zip 文件\"\n  # 先解压到临时目录\n  cd $DEPLOY_DIR\n  unzip -o -q dist.zip\n  \n  # 检查解压后的结构\n  if [ -d \"$DEPLOY_DIR/dist\" ]; then\n    # 解压后有 dist 目录，复制其内容\n    cp -r $DEPLOY_DIR/dist/* $TARGET_DIR/\n    echo \"已解压 dist.zip 并复制到 $TARGET_DIR\"\n  else\n    # 解压后直接是文件，移动到目标目录\n    mv $DEPLOY_DIR/* $TARGET_DIR/ 2>/dev/null || true\n    echo \"已解压 dist.zip 到 $TARGET_DIR\"\n  fi\nelif [ -f \"$DEPLOY_DIR/dist.tar.gz\" ]; then\n  tar -xzf $DEPLOY_DIR/dist.tar.gz -C $DEPLOY_DIR\n  cp -r $DEPLOY_DIR/dist/* $TARGET_DIR/\n  echo \"已解压 dist.tar.gz 到 $TARGET_DIR\"\nelif [ -d \"$DEPLOY_DIR/dist\" ]; then\n  cp -r $DEPLOY_DIR/dist/* $TARGET_DIR/\n  echo \"已复制 dist 目录到 $TARGET_DIR\"\nelse\n  echo \"错误: 未找到构建产物（dist目录或压缩包）\"\n  exit 1\nfi\n\n# 3. 设置文件权限\necho \"[步骤3] 设置文件权限...\"\nchmod -R 755 $TARGET_DIR\n\necho \"========================================\"\necho \"部署完成！\"\necho \"部署目录: $TARGET_DIR\"\necho \"访问路径: http://your-domain/$PROJECT_NAME\"\necho \"========================================\"', '/home/deploy/', 8080, 'VUE', NULL, 'npm install && npm run build', 'dist', 1, '2025-11-28 16:21:51', '2025-12-03 14:34:02', 1, 'development');
INSERT INTO `t_project` VALUES (5, NULL, '12', '23', '12', '23', '23', '23', 0, '#!/bin/bash\n# Java 项目部署脚本\n\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署Java应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 查找新上传的jar（备份操作已在上传前完成）\necho \"[步骤2] 查找jar文件...\"\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\.bak$\' | head -n 1)\n\nif [ -z \"$JAR_FILE\" ] || [ ! -f \"$JAR_FILE\" ]; then\n  echo \"错误: 未找到可用的jar文件\"\n  exit 1\nfi\n\nJAR_NAME=$(basename \"$JAR_FILE\")\necho \"找到jar文件: $JAR_NAME\"\n\n# 3. 启动新应用\necho \"[步骤3] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT \"$JAR_FILE\" > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"JAR文件: $JAR_NAME\"\necho \"日志文件: $LOG_FILE\"\n\n# 4. 等待应用启动并实时显示日志\necho \"[步骤4] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n  \n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n    \n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/', 8080, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-02 14:16:07', '2025-12-02 15:13:04', 1, 'test');
INSERT INTO `t_project` VALUES (6, NULL, '1212', '23', '23', '23', '23', '23', 0, '#!/bin/bash\n# Java 项目部署脚本\n\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署Java应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 查找新上传的jar（备份操作已在上传前完成）\necho \"[步骤2] 查找jar文件...\"\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\.bak$\' | head -n 1)\n\nif [ -z \"$JAR_FILE\" ] || [ ! -f \"$JAR_FILE\" ]; then\n  echo \"错误: 未找到可用的jar文件\"\n  exit 1\nfi\n\nJAR_NAME=$(basename \"$JAR_FILE\")\necho \"找到jar文件: $JAR_NAME\"\n\n# 3. 启动新应用\necho \"[步骤3] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT \"$JAR_FILE\" > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"JAR文件: $JAR_NAME\"\necho \"日志文件: $LOG_FILE\"\n\n# 4. 等待应用启动并实时显示日志\necho \"[步骤4] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n  \n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n    \n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/', 8080, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-02 14:16:47', '2025-12-02 14:20:32', 1, 'production');
