>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/master/', 8888, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-02 14:26:50', '2025-12-03 14:33:57', 1, 'production');
