/dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n    \n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n    \n    sleep 1\n  done\n  \n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/dev/', 8888, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-02 14:29:56', '2025-12-03 14:33:55', 1, 'development');
INSERT INTO `t_project` VALUES (1996106642080358401, 2004079440002195457, 'hoyozero-nav-server', '宏宇项目导航后台', 'https://gitee.com/hoyozero/hoyozero-nav-server.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java项目部署脚本\n\nAPP_NAME=\"hoyozero-nav-server\"\nAPP_PORT=8080\nDEPLOY_PATH=\"/home/deploy/\"\n\n# 进入部署目录\ncd ${DEPLOY_PATH} || exit 1\n\n# 停止旧应用\nif [ -f \"${APP_NAME}.pid\" ]; then\n  OLD_PID=$(cat ${APP_NAME}.pid)\n  if ps -p $OLD_PID > /dev/null; then\n    echo \"停止旧应用 PID: $OLD_PID\"\n    kill $OLD_PID\n    sleep 3\n  fi\nfi\n\n# 备份旧版本\nif [ -f \"${APP_NAME}.jar\" ]; then\n  BACKUP_NAME=\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\"\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\n  echo \"已备份旧版本: ${BACKUP_NAME}\"\nfi\n\n# 启动新应用\necho \"启动新应用...\"\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\necho $! > ${APP_NAME}.pid\n\necho \"部署完成！应用端口: ${APP_PORT}\"\necho \"查看日志: tail -f logs/${APP_NAME}.log\"', '/home/deploy/', 8080, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-03 14:38:04', '2025-12-03 14:38:04', 0, 'production');
INSERT INTO `t_project` VALUES (1996490925164937217, NULL, 'test-code', '测试项目', 'https://gitee.com/hoyozero/test-code.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java项目部署脚本\n\nAPP_NAME=\"test-code\"\nAPP_PORT=8080\nDEPLOY_PATH=\"/home/deploy/\"\n\n# 进入部署目录\ncd ${DEPLOY_PATH} || exit 1\n\n# 停止旧应用\nif [ -f \"${APP_NAME}.pid\" ]; then\n  OLD_PID=$(cat ${APP_NAME}.pid)\n  if ps -p $OLD_PID > /dev/null; then\n    echo \"停止旧应用 PID: $OLD_PID\"\n    kill $OLD_PID\n    sleep 3\n  fi\nfi\n\n# 备份旧版本\nif [ -f \"${APP_NAME}.jar\" ]; then\n  BACKUP_NAME=\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\"\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\n  echo \"已备份旧版本: ${BACKUP_NAME}\"\nfi\n\n# 启动新应用\necho \"启动新应用...\"\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\necho $! > ${APP_NAME}.pid\n\necho \"部署完成！应用端口: ${APP_PORT}\"\necho \"查看日志: tail -f logs/${APP_NAME}.log\"', '/home/deploy/', 8080, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-04 16:05:04', '2025-12-25 15:23:54', 1, 'test');
INSERT INTO `t_project` VALUES (1998370634521866242, NULL, 'customer-code', '', 'https://gitee.com/hoyozero/customer-code.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java 项目部署脚本\n\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署Java应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 查找新上传的jar（备份操作已在上传前完成）\necho \"[步骤2] 查找jar文件...\"\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\.bak$\' | head -n 1)\n\nif [ -z \"$JAR_FILE\" ] || [ ! -f \"$JAR_FILE\" ]; then\n  echo \"错误: 未找到可用的jar文件\"\n  exit 1\nfi\n\nJAR_NAME=$(basename \"$JAR_FILE\")\necho \"找到jar文件: $JAR_NAME\"\n\n# 3. 启动新应用\necho \"[步骤3] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT \"$JAR_FILE\" > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"JAR文件: $JAR_NAME\"\necho \"日志文件: $LOG_FILE\"\n\n# 4. 等待应用启动并实时显示日志\necho \"[步骤4] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n\n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n\n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n\n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n\n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n\n    sleep 1\n  done\n\n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/', 8002, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-09 20:34:22', '2025-12-25 14:56:03', 1, 'production');
INSERT INTO `t_project` VALUES (1999035333009694721, NULL, 'qoder-code', '', 'https://gitee.com/hoyozero/qoder-code.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java 项目部署脚本\n\nAPP_PORT={{appPort}}\nDEPLOY_DIR=\"{{uploadPath}}\"\nLOG_FILE=\"$DEPLOY_DIR/app.log\"\n\necho \"========================================\"\necho \"开始部署Java应用\"\necho \"========================================\"\n\n# 1. 停止旧进程\necho \"[步骤1] 正在停止旧进程...\"\nPID=$(lsof -t -i:$APP_PORT 2>/dev/null)\nif [ ! -z \"$PID\" ]; then\n  kill -15 $PID\n  sleep 3\n  if ps -p $PID > /dev/null 2>&1; then\n    kill -9 $PID\n    echo \"已强制停止进程: $PID\"\n  else\n    echo \"已优雅停止进程: $PID\"\n  fi\nelse\n  echo \"未找到运行中的进程\"\nfi\n\nsleep 2\n\n# 2. 查找新上传的jar（备份操作已在上传前完成）\necho \"[步骤2] 查找jar文件...\"\nJAR_FILE=$(ls -t $DEPLOY_DIR/*.jar 2>/dev/null | grep -v \'\\.bak$\' | head -n 1)\n\nif [ -z \"$JAR_FILE\" ] || [ ! -f \"$JAR_FILE\" ]; then\n  echo \"错误: 未找到可用的jar文件\"\n  exit 1\nfi\n\nJAR_NAME=$(basename \"$JAR_FILE\")\necho \"找到jar文件: $JAR_NAME\"\n\n# 3. 启动新应用\necho \"[步骤3] 正在启动应用...\"\ncd $DEPLOY_DIR\n\n# 清空旧日志\n> $LOG_FILE\n\n# 后台启动应用\nnohup java -jar -Xms512m -Xmx1024m -Dserver.port=$APP_PORT \"$JAR_FILE\" > $LOG_FILE 2>&1 &\nNEW_PID=$!\n\necho \"应用已启动，PID: $NEW_PID\"\necho \"JAR文件: $JAR_NAME\"\necho \"日志文件: $LOG_FILE\"\n\n# 4. 等待应用启动并实时显示日志\necho \"[步骤4] 等待应用启动...\"\necho \"----------------------------------------\"\necho \"应用启动日志：\"\necho \"----------------------------------------\"\n\n# 实时显示日志并检测启动成功\nSTART_TIME=$(date +%s)\nTIMEOUT=60\nSTARTED=false\n\n# 使用 tail -f 实时显示日志，同时检测启动状态\n(\n  tail -f $LOG_FILE &\n  TAIL_PID=$!\n\n  while true; do\n    CURRENT_TIME=$(date +%s)\n    ELAPSED=$((CURRENT_TIME - START_TIME))\n\n    # 检查超时\n    if [ $ELAPSED -gt $TIMEOUT ]; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"警告: 应用启动超时（60秒）\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n\n    # 检查端口是否已监听\n    if lsof -t -i:$APP_PORT > /dev/null 2>&1; then\n      sleep 2\n      kill $TAIL_PID 2>/dev/null\n      STARTED=true\n      break\n    fi\n\n    # 检查进程是否还在运行\n    if ! ps -p $NEW_PID > /dev/null 2>&1; then\n      kill $TAIL_PID 2>/dev/null\n      echo \"\"\n      echo \"----------------------------------------\"\n      echo \"错误: 应用进程已退出\"\n      echo \"请检查日志文件: $LOG_FILE\"\n      exit 1\n    fi\n\n    sleep 1\n  done\n\n  if [ \"$STARTED\" = true ]; then\n    echo \"\"\n    echo \"----------------------------------------\"\n    echo \"应用启动成功！\"\n    echo \"========================================\"\n    echo \"部署完成！\"\n    echo \"JAR文件: $JAR_NAME\"\n    echo \"应用端口: $APP_PORT\"\n    echo \"应用PID: $NEW_PID\"\n    echo \"日志文件: $LOG_FILE\"\n    echo \"========================================\"\n    exit 0\n  fi\n) || exit 1', '/home/deploy/', 8002, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-11 16:35:38', '2025-12-15 15:28:10', 1, 'production');
INSERT INTO `t_project` VALUES (2000474898488610817, NULL, 'test001111', '', '11', 'master', '', '123456', 1, '#!/bin/bash\n# Java项目部署脚本\n\nAPP_NAME=\"test001\"\nAPP_PORT=8080\nDEPLOY_PATH=\"/home/deploy/\"\n\n# 进入部署目录\ncd ${DEPLOY_PATH} || exit 1\n\n# 停止旧应用\nif [ -f \"${APP_NAME}.pid\" ]; then\n  OLD_PID=$(cat ${APP_NAME}.pid)\n  if ps -p $OLD_PID > /dev/null; then\n    echo \"停止旧应用 PID: $OLD_PID\"\n    kill $OLD_PID\n    sleep 3\n  fi\nfi\n\n# 备份旧版本\nif [ -f \"${APP_NAME}.jar\" ]; then\n  BACKUP_NAME=\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\"\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\n  echo \"已备份旧版本: ${BACKUP_NAME}\"\nfi\n\n# 启动新应用\necho \"启动新应用...\"\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\necho $! > ${APP_NAME}.pid\n\necho \"部署完成！应用端口: ${APP_PORT}\"\necho \"查看日志: tail -f logs/${APP_NAME}.log\"', '/home/deploy/', 8080, 'JAVA', NULL, 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-15 15:55:57', '2025-12-15 16:50:24', 1, 'development');
INSERT INTO `t_project` VALUES (2004093573535838209, 2004091385556185089, 'order-spider', '', 'https://gitee.com/hoyozero/order-sp.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java项目部署脚本\n\nAPP_NAME=\"order-spider\"\nAPP_PORT={{appPort}}\nDEPLOY_PATH=\"/www/wwwroot/\"\n\n# 进入部署目录\ncd ${DEPLOY_PATH} || exit 1\n\n# 停止旧应用\nif [ -f \"${APP_NAME}.pid\" ]; then\n  OLD_PID=$(cat ${APP_NAME}.pid)\n  if ps -p $OLD_PID > /dev/null; then\n    echo \"停止旧应用 PID: $OLD_PID\"\n    kill $OLD_PID\n    sleep 3\n  fi\nfi\n\n# 备份旧版本\nif [ -f \"${APP_NAME}.jar\" ]; then\n  BACKUP_NAME=\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\"\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\n  echo \"已备份旧版本: ${BACKUP_NAME}\"\nfi\n\n# 启动新应用\necho \"启动新应用...\"\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\necho $! > ${APP_NAME}.pid\n\necho \"部署完成！应用端口: ${APP_PORT}\"\necho \"查看日志: tail -f logs/${APP_NAME}.log\"', '/www/wwwroot/', 8082, 'JAVA', 'backend', 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-25 15:35:17', '2025-12-25 16:29:36', 1, 'production');
INSERT INTO `t_project` VALUES (2004107524512362498, 2004091385556185089, 'order-spider', '', 'https://gitee.com/hoyozero/order-sp.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java项目部署脚本\n\nAPP_NAME=\"\"\nAPP_PORT={{appPort}}\nDEPLOY_PATH=\"{{uploadPath}}\"\n\n# 进入部署目录\ncd ${DEPLOY_PATH} || exit 1\n\n# 创建必要的目录\nmkdir -p logs backup\n\n# 停止旧应用\nif [ -f \"${APP_NAME}.pid\" ]; then\n  OLD_PID=$(cat ${APP_NAME}.pid)\n  if ps -p $OLD_PID > /dev/null 2>&1; then\n    echo \"[INFO] Stopping old application (PID: $OLD_PID)...\"\n    kill $OLD_PID\n    sleep 3\n    # 强制停止\n    if ps -p $OLD_PID > /dev/null 2>&1; then\n      kill -9 $OLD_PID\n    fi\n  fi\n  rm -f ${APP_NAME}.pid\nfi\n\n# 备份旧版本\nif [ -f \"${APP_NAME}.jar\" ]; then\n  BACKUP_NAME=\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\"\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\n  echo \"[INFO] Backup old version: ${BACKUP_NAME}\"\nfi\n\n# 重命名新上传的jar包\nif [ -f \"*.jar\" ]; then\n  mv *.jar ${APP_NAME}.jar\nfi\n\n# 清空旧日志\necho \"\" > logs/${APP_NAME}.log\n\n# 启动新应用\necho \"[INFO] Starting new application...\"\necho \"[INFO] Application port: ${APP_PORT}\"\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\necho $! > ${APP_NAME}.pid\n\n# 等待应用启动\nsleep 2\n\n# 检查进程是否运行\nif ps -p $(cat ${APP_NAME}.pid) > /dev/null 2>&1; then\n  echo \"[SUCCESS] Application started successfully!\"\n  echo \"[INFO] PID: $(cat ${APP_NAME}.pid)\"\n  echo \"[INFO] Port: ${APP_PORT}\"\n  echo \"\"\n  echo \"[LOG] Application startup logs:\"\n  echo \"================================================\"\n  # 输出启动日志（10秒）\n  timeout 10 tail -f logs/${APP_NAME}.log 2>/dev/null || tail -n 50 logs/${APP_NAME}.log\n  echo \"================================================\"\n  echo \"[INFO] View full logs: tail -f logs/${APP_NAME}.log\"\nelse\n  echo \"[ERROR] Application failed to start!\"\n  echo \"[ERROR] Check logs: cat logs/${APP_NAME}.log\"\n  exit 1\nfi', '/www/wwwroot/', 8082, 'JAVA', 'backend', 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-25 16:30:43', '2025-12-25 16:37:13', 1, 'production');
INSERT INTO `t_project` VALUES (2004109385558642690, 2004091385556185089, 'order-spider', '', 'https://gitee.com/hoyozero/order-sp.git', 'master', 'wqexpore@163.com', 'wq850994281', 1, '#!/bin/bash\n# Java项目部署脚本\n\nAPP_NAME=\"order-spider\"\nAPP_PORT={{appPort}}\nDEPLOY_PATH=\"{{uploadPath}}\"\n\n# 进入部署目录\ncd ${DEPLOY_PATH} || exit 1\n\n# 创建必要的目录\nmkdir -p logs backup\n\n# 停止旧应用\nif [ -f \"${APP_NAME}.pid\" ]; then\n  OLD_PID=$(cat ${APP_NAME}.pid)\n  if ps -p $OLD_PID > /dev/null 2>&1; then\n    echo \"[INFO] Stopping old application (PID: $OLD_PID)...\"\n    kill $OLD_PID\n    sleep 3\n    # 强制停止\n    if ps -p $OLD_PID > /dev/null 2>&1; then\n      kill -9 $OLD_PID\n    fi\n  fi\n  rm -f ${APP_NAME}.pid\nfi\n\n# 备份旧版本\nif [ -f \"${APP_NAME}.jar\" ]; then\n  BACKUP_NAME=\"${APP_NAME}_$(date +%Y%m%d_%H%M%S).jar\"\n  mv ${APP_NAME}.jar backup/${BACKUP_NAME}\n  echo \"[INFO] Backup old version: ${BACKUP_NAME}\"\nfi\n\n# 查找并重命名新上传的jar包\necho \"[INFO] Looking for uploaded jar file...\"\nUPLOADED_JAR=$(ls -t *.jar 2>/dev/null | head -n 1)\nif [ -n \"$UPLOADED_JAR\" ]; then\n  if [ \"$UPLOADED_JAR\" != \"${APP_NAME}.jar\" ]; then\n    mv \"$UPLOADED_JAR\" \"${APP_NAME}.jar\"\n    echo \"[INFO] Renamed $UPLOADED_JAR to ${APP_NAME}.jar\"\n  fi\nelse\n  echo \"[ERROR] No jar file found in current directory!\"\n  exit 1\nfi\n\n# 清空旧日志\necho \"\" > logs/${APP_NAME}.log\n\n# 启动新应用\necho \"[INFO] Starting new application...\"\necho \"[INFO] Application port: ${APP_PORT}\"\nnohup java -jar ${APP_NAME}.jar --server.port=${APP_PORT} > logs/${APP_NAME}.log 2>&1 &\nNEW_PID=$!\necho $NEW_PID > ${APP_NAME}.pid\necho \"[INFO] Application PID: $NEW_PID\"\n\n# 等待应用启动（输出启动日志）\necho \"\"\necho \"[LOG] Application startup logs:\"\necho \"================================================\"\nsleep 3\n# 输出启动日志，最多10秒\ntimeout 10 tail -f logs/${APP_NAME}.log 2>/dev/null &\nTAIL_PID=$!\nsleep 10\nkill $TAIL_PID 2>/dev/null\necho \"================================================\"\n\n# 检查进程是否运行\nif ps -p $NEW_PID > /dev/null 2>&1; then\n  echo \"[SUCCESS] Application is running!\"\n  echo \"[INFO] PID: $NEW_PID\"\n  echo \"[INFO] Port: ${APP_PORT}\"\n  echo \"[INFO] View logs: tail -f logs/${APP_NAME}.log\"\nelse\n  echo \"[WARNING] Process check: Application process not found\"\n  echo \"[INFO] This might be normal if the application starts quickly\"\n  echo \"[INFO] Check logs for details: tail -n 50 logs/${APP_NAME}.log\"\nfi', '/www/wwwroot/', 8082, 'JAVA', 'backend', 'mvn clean package -DskipTests', 'target/*.jar', NULL, '2025-12-25 16:38:07', '2025-12-25 16:42:05', 0, 'production');
